ST.xhtml:
// =============================================================================
// 场景：EL6022 串口模块或 ADS 读到设备 ASCII 应答（如 'SN:0421' + 0x00），
//       缓冲是 256 字节固定数组；需要转成 PLC STRING 后用 FIND 提取序列号。
// 价值：手写循环要 10+ 行处理 0x00 终止符和越界；本函数一行搞定，返回值
//       直接是 T_MaxString，可立即送 FIND / MID / 写入数据库字段。
// 验证步骤：
//   1. 登录后初始 arRxBuffer 是全 0，sDeviceTag = '' （空串）。
//   2. 写 arRxBuffer[0]:=16#53; arRxBuffer[1]:=16#4E; arRxBuffer[2]:=16#3A;
//      arRxBuffer[3]:=16#30; arRxBuffer[4]:=16#34; arRxBuffer[5]:=16#32;
//      arRxBuffer[6]:=16#31; arRxBuffer[7]:=16#00; （ASCII 'SN:0421' + 0x00）
//   3. 写 bParseRequest := TRUE 触发一次解析。
//   4. 在线 monitor sDeviceTag 应为 'SN:0421'，且 bParseRequest 自动复位为 FALSE。
//   5. 把 arRxBuffer[7] 改成 16#00 之外的值（去掉终止符），重置 bParseRequest，
//      会发现 sDeviceTag 把后续未清零的字节也拼进来——印证 §5 的"无终止符就读满"陷阱。
// =============================================================================

// 上电默认值演示：模拟 EL6022 接收 'Hi' (0x48 0x69) 后跟 0x00 终止
arRxBuffer[0] := 16#48;
arRxBuffer[1] := 16#69;
arRxBuffer[2] := 16#00;

// 单次调用形式：完成转换后立即复位请求位，避免每周期重复执行浪费
IF bParseRequest THEN
    sDeviceTag := BYTEARR_TO_MAXSTRING(arRxBuffer);
    bParseRequest := FALSE;
END_IF;
